export type Result<T, E> =
  | { type: 'ok'; value: T }
  | { type: 'err'; error: E };

export const ok = <T>(value: T): Result<T, never> => ({
  type: 'ok',
  value,
});

export const err = <E>(error: E): Result<never, E> => ({
  type: 'err',
  error,
});

export function isOk<T, E>(result: Result<T, E>): result is Extract<Result<T, E>, { type: 'ok' }> {
  return result.type === 'ok';
}

export function isErr<T, E>(result: Result<T, E>): result is Extract<Result<T, E>, { type: 'err' }> {
  return result.type === 'err';
}

export const map = <T, E, U>(
  result: Result<T, E>,
  fn: (value: T) => U
): Result<U, E> => {
  if (isOk(result)) {
    return ok(fn(result.value));
  }
  return err(result.error);
};

export const unwrapOr = <T, E>(
  result: Result<T, E>,
  defaultValue: T
): T => {
  if (isOk(result)) {
    return result.value;
  }
  return defaultValue;
};
